cd /Users/dev/workspace/vivarium/experiments/tier3/results/workspace && python3 - <<'EOF'
import json, glob

total = 0
count = 0
for path in sorted(glob.glob('data/*.jsonl')):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            rec = json.loads(line)
            if rec.get('kind') != 'span':
                continue
            el = rec.get('body', {}).get('span', {}).get('elapsed')
            if el is None:
                continue
            v = el['value']; u = el['unit']
            if u == 'ms':
                total += v
            elif u == 'us':
                total += v // 1000
            elif u == 's':
                total += v * 1000
            else:
                raise ValueError(f'bad unit {u}')
            count += 1

print('spans with elapsed:', count)
print('total ms:', total)
EOF
